import { initMap, createRoute, addWorkshops, addCasinos } from 'data:application/javascript;base64,';
import { TruckController } from 'data:application/javascript;base64,';
import { MissionGenerator } from 'data:application/javascript;base64,';
import { ACHIEVEMENTS } from 'data:application/javascript;base64,';
import { GameState } from 'data:application/javascript;base64,';
import { UIManager } from 'data:application/javascript;base64,';
import { VEHICLE_CATALOG, COMPANY_FOUNDING_COST } from 'data:application/javascript;base64,';
import { calculateDistance } from 'data:application/javascript;base64,';
import { RadioManager } from 'data:application/javascript;base64,';
import { PoliceChaser } from 'data:application/javascript;base64,';
import { NPCManager } from 'data:application/javascript;base64,';
import { CasinoManager } from 'data:application/javascript;base64,';
import { ChatManager } from 'data:application/javascript;base64,';

class GlobalTruckerGame {
    constructor() {
        this.state = new GameState(this); // Pass game instance to state for callbacks
        this.ui = new UIManager(this);
        
        this.map = null;
        this.truck = null;
        this.missionGenerator = null;
        this.currentMission = null;
        this.radioManager = null;
        this.casinoManager = new CasinoManager(this);
        this.chatManager = new ChatManager(this);

        this.initializeGame();
        this.ui.init(); // Initialize UI after game components are set up
        this.handleAchievementChecks(); // Check achievements on startup based on loaded state
        this.initDayNightCycle();
        this.setupNitro();
    }
    
    setupNitro() {
        this.nitroActive = false;
        this.nitroBtn = document.getElementById('nitro-btn');
        this.mapContainer = document.getElementById('map');
        
        // UI button listeners
        if (this.nitroBtn) {
            this.nitroBtn.addEventListener('mousedown', () => this.activateNitro());
            this.nitroBtn.addEventListener('mouseup', () => this.deactivateNitro());
            this.nitroBtn.addEventListener('mouseleave', () => this.deactivateNitro());
            
            // Touch support
            this.nitroBtn.addEventListener('touchstart', (e) => { e.preventDefault(); this.activateNitro(); });
            this.nitroBtn.addEventListener('touchend', (e) => { e.preventDefault(); this.deactivateNitro(); });
        }

        // Shift key listener
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Shift') this.activateNitro();
        });
        document.addEventListener('keyup', (e) => {
            if (e.key === 'Shift') this.deactivateNitro();
        });
    }

    activateNitro() {
        this.nitroActive = true;
        if (this.nitroBtn) this.nitroBtn.classList.add('active');
        if (this.mapContainer) this.mapContainer.classList.add('map-shake');
        if (this.truck && this.truck.vehicleMarker && this.truck.vehicleMarker.getElement()) {
            this.truck.vehicleMarker.getElement().classList.add('nitro-active');
        }
    }

    deactivateNitro() {
        this.nitroActive = false;
        if (this.nitroBtn) this.nitroBtn.classList.remove('active');
        if (this.mapContainer) this.mapContainer.classList.remove('map-shake');
        if (this.truck && this.truck.vehicleMarker && this.truck.vehicleMarker.getElement()) {
            this.truck.vehicleMarker.getElement().classList.remove('nitro-active');
        }
    }
    
    initDayNightCycle() {
        this.gameTimeMinutes = 720; // Start at 12:00 PM
        this.timeDisplay = document.getElementById('time-display');
        this.mapContainer = document.getElementById('map');
        
        setInterval(() => {
            this.gameTimeMinutes += 1; // 1 in-game min per real second
            if (this.gameTimeMinutes >= 1440) this.gameTimeMinutes = 0;
            
            const hours = Math.floor(this.gameTimeMinutes / 60);
            const minutes = this.gameTimeMinutes % 60;
            const ampm = hours >= 12 ? 'PM' : 'AM';
            const displayHours = hours % 12 || 12;
            const displayMinutes = minutes < 10 ? '0' + minutes : minutes;
            
            // Determine day/night
            const isNight = hours >= 19 || hours < 6; // Night 7PM to 6AM
            const icon = isNight ? '🌙' : '☀️';
            
            if (this.timeDisplay) {
                this.timeDisplay.textContent = `${icon} ${displayHours}:${displayMinutes} ${ampm}`;
            }
            
            if (this.mapContainer) {
                if (isNight) {
                    this.mapContainer.classList.add('map-night-filter');
                    this.mapContainer.classList.remove('map-day-filter');
                } else {
                    this.mapContainer.classList.add('map-day-filter');
                    this.mapContainer.classList.remove('map-night-filter');
                }
            }
        }, 300); // Fast cycle: 300ms per in-game minute
    }

    // --- Game Initialization & Setup ---
    initializeGame() {
        try {
            // Force cleanup of any existing map
            const mapContainer = document.getElementById('map');
            if (mapContainer && mapContainer._leaflet_map) {
                mapContainer._leaflet_map.remove();
                mapContainer._leaflet_map = null;
            }

            // Initialize map
            this.map = initMap();
            
            // Add workshops and casinos to the map
            this.workshops = addWorkshops(this.map);
            this.casinos = addCasinos(this.map);
            
            this.missionGenerator = new MissionGenerator(this.map);
            
            // Create truck or plane based on selected vehicle
            // Destroy previous truck controller if it exists
            if (this.truck) {
                this.truck.destroy();
                this.truck = null;
            }
            this.truck = new TruckController(this.map, this, this.state.selectedVehicle);

            // Ensure joystick state is applied to the new truck controller
            this.toggleJoystick(this.ui.joystickEnabled);

            // Initialize radio manager
            if (this.radioManager) {
                this.radioManager.destroy();
            }
            this.radioManager = new RadioManager(this);
            
            this.currentMission = null; // Clear previous mission data
            this.generateNewMission(); // Generate the first mission

            // Fake Multiplayer
            this.npcs = new NPCManager(this);
            this.npcs.init();

        } catch (error) {
            console.error("Game initialization failed:", error);
            this.ui.notifications.showModal("Error", "Failed to start the game. Please refresh the page.");
        }
    }

    // --- Mission Logic ---
    generateNewMission() {
        const vehicleCategory = this.getVehicleCategory(this.state.selectedVehicle);
        this.currentMission = this.missionGenerator.createMission(vehicleCategory);
        
        if (this.truck) {
            this.truck.setPosition(this.currentMission.startCoords);
        }

        // Create route between start and destination
        createRoute(this.map, 
            this.currentMission.startCoords, 
            this.currentMission.destinationCoords
        );

        this.ui.updateMissionUI(this.currentMission);

        this.activeHazards = [];

        // Spawn police if it's a smuggler mission
        if (this.currentMission.cargo.isSmuggler) {
            this.ui.notifications.showModal("High Risk Contract!", "You are hauling contraband. Keep an eye out for authorities... they are tracking you!", [{text: "I'm ready", className: "btn-danger"}]);
            
            // Spawn a police chaser roughly off-center from the start position
            setTimeout(() => {
                const spawnLat = this.currentMission.startCoords[0] + (Math.random() > 0.5 ? 2 : -2);
                const spawnLng = this.currentMission.startCoords[1] + (Math.random() > 0.5 ? 2 : -2);
                this.activeHazards.push(new PoliceChaser(this, [spawnLat, spawnLng]));
            }, 2000);
        }
    }

    completeMission() {
        let missionReward = this.currentMission.cargo.value;
        let bonus = 0;

        if (this.state.companyStarted) {
            bonus = Math.round(missionReward * 0.25); // 25% company bonus
            missionReward += bonus;
        }
        
        this.state.money += missionReward;

        // Update stats BEFORE checking achievements
        this.state.updateMissionStats(this.currentMission, missionReward, this.missionGenerator);

        // Grant XP
        const distance = this.calculateDistance(this.currentMission.startCoords, this.currentMission.destinationCoords);
        const xpGained = Math.round(distance / 10) + 20; // Base 20xp + distance bonus
        
        // Use state's addXP method which handles leveling up and its bonuses internally
        const { leveledUp, levelUpInfo } = this.state.addXP(xpGained);

        // Clear hazards
        if (this.activeHazards) {
            this.activeHazards.forEach(h => h.destroy());
            this.activeHazards = [];
        }

        // Simple completion alert and floating text
        this.ui.notifications.showModal("Mission Complete!", `+ $${this.currentMission.cargo.value.toLocaleString()}${bonus > 0 ? `<br>Company Bonus: + $${bonus.toLocaleString()}` : ''}<br>Total: $${missionReward.toLocaleString()}<br><br>+ ${xpGained} XP`);
        
        this.ui.notifications.showFloatingText('+$' + missionReward.toLocaleString(), 'money');
        setTimeout(() => this.ui.notifications.showFloatingText('+' + xpGained + ' XP', 'xp'), 300);

        // If levelUp happened, the state's addXP would have already triggered an alert/callback.
        // We can remove the check here if the state handles the level up UI/alerts.
        // Assuming State handles level up notification:
        // if (leveledUp) { ... } // Removed this block

        this.ui.updateAllUI(); // Update all UI elements
        
        this.handleAchievementChecks(); // Check achievements based on updated stats/state
        this.state.save();

        this.generateNewMission(); // Generate the next mission
    }
    
    busted() {
        // Called when a hazard catches the player
        if (this.truck && this.truck.vehicleMarker) {
             this.truck.setPosition([this.truck.vehicleMarker.getLatLng().lat, this.truck.vehicleMarker.getLatLng().lng]); // Stop routing
        }
        
        // Fine them
        const fine = Math.floor(this.state.money * 0.2); 
        this.state.money -= fine;
        
        // Clear hazards
        if (this.activeHazards) {
            this.activeHazards.forEach(h => h.destroy());
            this.activeHazards = [];
        }
        
        this.state.save();
        this.ui.updateAllUI();
        
        this.ui.notifications.showModal("Busted!", `The authorities caught you! Your cargo has been confiscated and you were fined $${fine.toLocaleString()}.`, [{
            text: "Pay Fine",
            onClick: () => {
                this.currentMission = null;
                this.generateNewMission();
            }
        }]);
    }
    
    // --- Company Logic ---
    startCompany() {
        if (this.state.money >= COMPANY_FOUNDING_COST) {
            this.state.money -= COMPANY_FOUNDING_COST;
            this.state.companyStarted = true;
            this.ui.notifications.showModal("Company Founded!", "Congratulations! You've founded your own logistics company. You'll now receive a bonus on all completed jobs.");
            this.ui.updateAllUI();
            this.handleAchievementChecks(); // Check for company achievement
            this.state.save();
        } else {
            // This case shouldn't be reachable if button is disabled/hidden correctly, but good practice
            this.ui.notifications.showToast(`You need $${COMPANY_FOUNDING_COST.toLocaleString()} to start a company.`, 'error');
        }
    }

    // --- Vehicle Management ---
    handleVehicleSelection(vehicleId) {
        const vehicle = VEHICLE_CATALOG[vehicleId];
        const isOwned = this.state.ownedVehicles.includes(vehicleId);
        const isSelected = this.state.selectedVehicle === vehicleId;

        if (isSelected) return; // Nothing to do

        if (isOwned) {
            // Just select it
            this.state.selectedVehicle = vehicleId;
            this.initializeGame(); // Re-initialize to switch vehicle
        } else if (this.state.money >= vehicle.price) {
            // Purchase and select
            this.state.money -= vehicle.price;
            this.state.ownedVehicles.push(vehicleId);
            this.state.selectedVehicle = vehicleId;
            this.initializeGame(); // Re-initialize to switch vehicle
        } else {
             // Cannot afford
            this.ui.notifications.showToast(`You need $${(vehicle.price - this.state.money).toLocaleString()} more to buy the ${vehicle.name}.`, 'error');
            this.ui.updateAllUI(); // Update UI just in case
            return;
        }

        this.ui.updateAllUI(); // Update shop UI, money, etc.
        this.handleAchievementChecks(); // Check for vehicle purchase achievement
        this.state.save();
    }
    
    getVehicleCategory(vehicleId) {
        return VEHICLE_CATALOG[vehicleId]?.category || 'truck';
    }

    // --- Controls ---
    toggleJoystick(enabled) {
        // ui.js already updates its internal state. This method just orchestrates the truck controller.
        if (this.truck) {
            if (enabled) {
                this.truck.enableJoystick();
            } else {
                this.truck.disableJoystick();
            }
        }
    }
    
    // --- Utility Methods ---
    calculateDistance(coords1, coords2) {
        return calculateDistance(coords1, coords2);
    }

    openWorkshop() {
        this.ui.showWorkshopPanel();
    }

    openCasino(casinoName) {
        this.casinoManager.open(casinoName);
    }

    upgradeVehicle(upgradeType) {
        // Delegate to state which handles the upgrade logic and costs
        const result = this.state.upgradeVehicle(upgradeType);
        if (result.success) {
            this.ui.notifications.showToast(`${upgradeType} upgraded! -$${result.cost}`, 'success');
            this.ui.updateAllUI();
            // Apply upgrades to current truck controller
            if (this.truck) {
                this.truck.applyUpgrades(this.state.vehicleUpgrades);
            }
        } else {
            this.ui.notifications.showToast(result.message, 'error');
        }
    }

    // --- Achievements ---
    handleAchievementChecks() {
         for (const id in ACHIEVEMENTS) {
            if (!this.state.achievementsUnlocked.includes(id)) {
                const achievement = ACHIEVEMENTS[id];
                // Check if the achievement condition is met using current state/stats
                if (achievement.check(this.state.stats, this.state)) {
                    this.unlockAchievement(id, achievement);
                }
            }
        }
    }

    unlockAchievement(id, achievement) {
        this.state.unlockAchievement(id); // State handles adding to list

        let rewardText = '';
        if (achievement.reward) {
            if (achievement.reward.xp) {
                // Grant XP directly via state's addXP method
                 const { leveledUp, levelUpInfo } = this.state.addXP(achievement.reward.xp);
                 // State's addXP should handle potential level-up notifications
                 rewardText += `+${achievement.reward.xp} XP `;
            }
            if (achievement.reward.money) {
                this.state.money += achievement.reward.money; // Grant money directly
                rewardText += `+$${achievement.reward.money.toLocaleString()}`;
            }
        }

        // Use a timeout to show this alert after other potential alerts (like level up)
        setTimeout(() => {
            this.ui.notifications.showModal("🏆 Achievement Unlocked! 🏆", `${achievement.name}<br>${achievement.description}<br><br>Reward: ${rewardText}`);
            // Update all UI after alerts and state changes
            this.ui.updateAllUI();
        }, 100); // Small delay


        this.ui.updateAchievementsUI(this.state.achievementsUnlocked); // Update display if it's open
        this.state.save();
    }

    // --- Save/Reset ---
    resetProgress() {
        this.ui.notifications.showModal("Reset Progress", "Are you sure you want to reset all your progress? This cannot be undone.", [
            { text: "Cancel", className: "btn-secondary", onClick: null },
            { text: "Reset", className: "btn-danger", onClick: () => {
                this.state.reset(); // State handles the reset
                window.location.reload(); // Reload to restart with default state
            }}
        ]);
    }

    // --- Removed Methods (now handled by State or UI) ---
    // removed loadState() {}
    // removed saveState() {}
    // removed calculateXpForNextLevel() {} // Now in State
    // removed addXP() {} // Now in State
    // removed levelUp() {} // Now in State
    // removed updateLevelUI() {} // Now in UI
    // removed updateMoneyUI() {} // Now in UI
    // removed updateCompanyStatusUI() {} // Now in UI
    // removed updateMissionUI() {} // Now in UI
    // removed updateSelectedVehicleUI() {} // Now in UI
    // removed setupVehicleShop() {} // Now in UI
    // removed setupControlsToggle() {} // Now in UI
    // removed setupResetButton() {} // Now in UI (event listener setup)
    // removed setupAchievementsPanel() {} // Now in UI (event listener setup)
    // removed updateAchievementsUI() {} // Now in UI
    // removed setupGameLoop() {} // No longer needed as initializeGame generates first mission
}

// Start the game automatically when the page loads
document.addEventListener('DOMContentLoaded', () => {
    window.gameInstance = new GlobalTruckerGame();
});

export default GlobalTruckerGame;